mapper.update:
update sys_dept d join live_ding_dept_bind b on b.sys_dept_id=d.dept_id
set d.status='1',d.update_by=#{username},d.update_time=sysdate()
where b.sync_batch<>#{syncBatch}

mapper.select:
select b.ding_user_id dingUserId,b.user_id userId,u.user_name userName,u.status
from live_ding_user_bind b join sys_user u on u.user_id=b.user_id
where b.ding_user_id=#{dingUserId}

select shop_id shopId,shop_code shopCode,shop_name shopName,platform_code platformCode, platform_name platformName,owner_name ownerName,status,remark from erp_shop
and (shop_code like concat('%',#{keyword},'%') or shop_name like concat('%',#{keyword},'%') or platform_name like concat('%',#{keyword},'%')) and status=#{status}
order by status,shop_id desc

select gift_id giftId,gift_code giftCode,gift_name giftName from erp_gift
where gift_name=#{giftName}and gift_id<>#{excludeGiftId}
order by gift_id limit 1

select template_id templateId,template_name templateName,content_json contentJson,status,sort_order sortOrder,
  create_time createTime,update_time updateTime from live_quick_template where user_id=#{userId}
order by status,sort_order,template_id desc
